var a=`1326-leche-asada`;var t=`world-1326`;var r=`CL`;var n=`south-america`;var o=8;var l=229;var s={en:`Leche Asada`,ua:`Лече асада`};var d={en:`Leche Asada is a dish from Chile featuring chicken egg, whole cow milk, evaporated milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Лече асада, страва кухні країни Чилі з такими основними складниками: куряче яйце, цільне коров'яче молоко, концентроване молоко без цукру. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 9 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 9 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:9,i:[[`white-granulated-sugar`,160,`g`],[`water`,50,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`chicken-egg`,6,`pcs`],[`whole-cow-milk`,740,`ml`],[`evaporated-milk`,230,`ml`],[`vanilla-extract`,6,`ml`]]},{en:`Bake the egg custard gently in a water bath at about 160°C until set with a slight wobble; refrigerate before serving.`,ua:`Обережно випікайте яєчний крем на водяній бані при приблизно 160°C до застигання з легким тремтінням; охолодіть перед подаванням.`,t:[`poaching`],m:58,i:[]},{en:`Refrigerate the prepared mixture for about 150 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 150 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:150,i:[]}];var m={slug:a,id:t,country:`CL`,region:n,servings:8,minutes:229,title:s,text:d,steps:g};export{r as country,m as default,t as id,l as minutes,n as region,o as servings,a as slug,g as steps,d as text,s as title};